export function ComparePage() {
  const [summary,setSummary]=useState(true); const [change,setChange]=useState(1);
  const changes=[["Artículo 4°","Plazo de revisión modificado"],["Artículo 9°","Responsable de validación"],["Disposición transitoria","Nueva disposición agregada"]];
  return <><PageHeader title="Comparador documental" description="Analizá cambios textuales objetivos entre documentos o versiones." actions={<><Button variant="secondary" icon={<Download/>}>Exportar</Button><Button icon={<Sparkles/>}>Analizar diferencias</Button></>}/>
    <div className="compare-selectors"><label>Documento A<select><option>Resolución 120/2024 · v2</option></select></label><button><GitCompareArrows/></button><label>Documento B<select><option>Resolución 85/2025 · v1</option></select></label><label className="switch-label"><input type="checkbox" checked={summary} onChange={()=>setSummary(!summary)}/>Mostrar resumen</label></div>
    <div className="diff-stats"><span><i className="added"/> 18 adiciones</span><span><i className="removed"/> 7 eliminaciones</span><span><i className="modified"/> 4 modificaciones</span><div><button onClick={()=>setChange(Math.max(0,change-1))}><ChevronLeft/></button><b>Cambio {change+1} de {changes.length}</b><button onClick={()=>setChange(Math.min(changes.length-1,change+1))}><ChevronRight/></button></div></div>
    <div className={`comparison-workspace ${summary?"with-summary":""}`}><section className="diff-panel"><header><Badge>A</Badge><div><b>Resolución 120/2024</b><span>Versión 2 · 18 páginas</span></div></header><div className="diff-document"><small>ARTÍCULO 4° — PLAZOS</small><p>El área responsable deberá completar la revisión documental dentro de los <del>diez (10) días hábiles</del> contados desde la recepción.</p><p>La unidad de origen realizará la validación final antes del archivo.</p></div></section>
      <section className="diff-panel"><header><Badge tone="indigo">B</Badge><div><b>Resolución 85/2025</b><span>Versión 1 · 9 páginas</span></div></header><div className="diff-document"><small>ARTÍCULO 2° — MODIFICACIÓN</small><p>El área responsable deberá completar la revisión documental dentro de los <ins>quince (15) días hábiles</ins> contados desde la recepción.</p><p><ins>La Dirección de Archivo realizará la validación final.</ins></p></div></section>
      {summary&&<aside className="diff-summary"><h3>Resumen de cambios</h3><Alert title="Interpretación generada">Este resumen separa los cambios textuales de su posible impacto. Verificá siempre el texto original.</Alert>{changes.map((c,i)=><button className={change===i?"active":""} onClick={()=>setChange(i)}><span>{i+1}</span><div><b>{c[0]}</b><small>{c[1]}</small></div><ChevronRight/></button>)}</aside>}
    </div></>;
}

